-- Phase 4.x: complete IICL equipment-scoped component master for the current GP/RF POC.
--
-- Authoritative sources ONLY:
--   GP: IICL Dry Van Container - component codes reference guide, revised 11 June 2025.
--   RF: IICL Refrigerated Containers - component codes reference guide, version 7 October 2025.
--
-- Scope:
--   * 66 standard Dry Van/GP component codes from the IICL Dry Van section.
--   * 114 RF component codes documented in the IICL Refrigerated guide.
--   * Palletwide/Open Top codes are intentionally excluded from GP.
--   * COA-only supplemental codes are retired from the active classifier master.
--
-- IMPORTANT: component_codes is the complete equipment master. component_face_rules is
-- intentionally narrower: it exposes only components that are physically relevant to the
-- current six EXTERNAL fixed-camera views (R/L/D/F/T/B). Interior cargo-space and hidden
-- service-panel components remain in the master but are not sent to Qwen until the POC adds
-- an appropriate interior/service inspection view.

-- Retire older/non-IICL active definitions before inserting the authoritative IICL rows.
UPDATE component_codes
SET active=0,
    effective_to=COALESCE(effective_to,'2025-06-10')
WHERE equipment_type='GP'
  AND active=1
  AND (standard_name<>'IICL ECS' OR standard_version<>'2025-06-11');

UPDATE component_codes
SET active=0,
    effective_to=COALESCE(effective_to,'2025-10-06')
WHERE equipment_type='RF'
  AND active=1
  AND (standard_name<>'IICL ECS' OR standard_version<>'2025-10-07');

