-- Remove COA-only RF visual rules from active use now that the active master is IICL-only.
UPDATE component_visual_rules
SET active=0
WHERE equipment_type='RF' AND component_code IN ('PIM','PIS');

-- Keep the existing RF cladding rules internally consistent with the IICL-only master.
UPDATE component_visual_rules
SET confusable_with='PIC',
    negative_cues='Not the inner liner/cladding surface.'
WHERE equipment_type='RF' AND component_code='POC' AND active=1;

UPDATE component_visual_rules
SET confusable_with='POC',
    negative_cues='Not the external outer cladding/skin.'
WHERE equipment_type='RF' AND component_code='PIC' AND active=1;

-- Strengthen the exact GP Door distinction raised during POC testing:
-- LBG is the shaped guide; HWR is the generic fastening hardware attached to/near it.
UPDATE component_visual_rules
SET negative_cues='Not the locking-bar rod, bracket, or adjacent generic bolts/fasteners classified as HWR.',
    confusable_with='LBR,LBB,HWR'
WHERE equipment_type='GP' AND component_code='LBG'
  AND container_face='DOOR' AND overview_zone='ANY';

INSERT OR REPLACE INTO component_visual_rules
(equipment_type,component_code,container_face,overview_zone,visual_definition,positive_cues,negative_cues,confusable_with,force_review,source_reference,priority,active)
VALUES
('GP','HWR','DOOR','ANY',
 'Generic door hardware/fastener associated with another door component.',
 'Pinpoint is on the bolt, nut, fastener or generic securing hardware itself rather than on the shaped component it secures.',
 'Do not classify the locking-bar guide, bracket, rod, cam or handle body as HWR merely because hardware is attached to it.',
 'LBG,LBB,LBR,LBC,LBH,HWH',
 0,
 'IICL Dry Van component guide 2025-06-11, pp.5,20-21',
 115,
 1);
